<template>
  <div class="app-container stocktakes">
    <div class="heading"><h2>{{ t('库存盘点', 'Stocktakes') }}</h2><el-button v-if="can('add')" type="primary" :disabled="blocked" @click="startOpen = true">{{ t('新建盘点', 'New stocktake') }}</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="mb16" />
    <el-alert v-if="pending || pendingError" :title="pendingError || t('上次盘点操作结果尚未确认，新操作已暂停。', 'A count operation is unconfirmed. New operations are paused.')" type="warning" :closable="false" class="mb16"><el-button v-if="pending" :loading="busy" @click="retry">{{ t('重试原请求', 'Retry original request') }}</el-button></el-alert>
    <el-form inline @submit.prevent="search"><el-form-item :label="t('盘点单号', 'Reference')"><el-input v-model="keyword" :aria-label="t('盘点单号筛选', 'Reference filter')" clearable /></el-form-item><el-form-item><el-button type="primary" :loading="loading" @click="search">{{ t('搜索', 'Search') }}</el-button></el-form-item></el-form>
    <el-table :data="rows" v-loading="loading" border><el-table-column prop="reference" :label="t('盘点单号', 'Reference')" min-width="180" /><el-table-column :label="t('状态', 'Status')" width="140"><template #default="{row}">{{ status(row.status) }}</template></el-table-column><el-table-column :label="t('客户', 'Client')" min-width="160"><template #default="{row}">{{ label('clients',row.client) }}</template></el-table-column><el-table-column :label="t('仓库', 'Warehouse')" min-width="160"><template #default="{row}">{{ label('warehouses',row.warehouse) }}</template></el-table-column><el-table-column prop="createdAt" :label="t('建立时间', 'Created at')" min-width="210" /><el-table-column :label="t('操作', 'Actions')" width="100" fixed="right"><template #default="{row}"><el-button v-if="can('query')" link type="primary" :disabled="busy" @click="open(row.id)">{{ t('查看', 'View') }}</el-button></template></el-table-column></el-table>
    <pagination v-show="total > 0" :total="total" v-model:page="page" v-model:limit="pageSize" @pagination="load" />

    <el-dialog v-model="startOpen" :title="t('新建盘点', 'New stocktake')" width="min(620px, 96%)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy">
      <el-alert type="warning" :closable="false" :title="t('开始后将冻结此客户在所选库位的收发货、移库和预留变更，直到审核入账或取消。', 'Starting freezes this client’s receipts, dispatches, transfers and reservation changes at selected locations until approval or cancellation.')" class="mb16" />
      <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="mb16" />
      <el-form label-position="top" :disabled="blocked" @submit.prevent>
        <el-form-item :label="t('客户', 'Client')"><el-select v-model="form.client" :aria-label="t('客户', 'Client')" filterable remote :remote-method="q=>lookup('clients',q)"><el-option v-for="o in options.clients || []" :key="o.id" :value="o.id" :label="o.label" /></el-select></el-form-item>
        <el-form-item :label="t('仓库', 'Warehouse')"><el-select v-model="form.warehouse" :aria-label="t('仓库', 'Warehouse')" filterable remote :remote-method="q=>lookup('warehouses',q)"><el-option v-for="o in options.warehouses || []" :key="o.id" :value="o.id" :label="o.label" /></el-select></el-form-item>
        <el-form-item :label="t('盘点库位', 'Locations to count')"><el-select v-model="form.locations" :aria-label="t('盘点库位', 'Locations to count')" multiple filterable remote :disabled="!form.client || !form.warehouse" :remote-method="q=>lookup('locations',q,{warehouse:form.warehouse,client:form.client})"><el-option v-for="o in options.locations || []" :key="o.id" :value="o.id" :label="o.label" /></el-select></el-form-item>
        <el-form-item :label="t('盘点单号', 'Reference')"><el-input v-model="form.reference" :aria-label="t('新盘点单号', 'New count reference')" maxlength="120" /></el-form-item>
        <el-form-item :label="t('备注', 'Notes')"><el-input v-model="form.notes" type="textarea" maxlength="2000" /></el-form-item>
      </el-form>
      <template #footer><el-button :disabled="busy" @click="startOpen=false">{{ t('关闭', 'Close') }}</el-button><el-button type="primary" :disabled="blocked" :loading="busy" @click="create">{{ t('开始盘点并冻结', 'Start and freeze') }}</el-button></template>
    </el-dialog>

    <el-drawer v-model="opened" :title="t('盘点明细', 'Stocktake details')" size="min(1100px, 100%)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy">
      <template v-if="detail">
        <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="mb16" />
        <el-alert v-if="pending" type="warning" :closable="false" :title="t('操作结果尚未确认，请重试当前请求。', 'Operation unconfirmed. Retry this request.')" class="mb16"><el-button :loading="busy" @click="retry">{{ t('重试当前操作', 'Retry pending operation') }}</el-button></el-alert>
        <div class="heading"><h3>{{ detail.reference }}</h3><el-tag :type="detail.status === 'APPROVED' ? 'success' : 'warning'">{{ status(detail.status) }}</el-tag></div>
        <el-alert :type="countOpen(detail) ? 'warning' : 'info'" :closable="false" :title="countOpen(detail) ? t('相关库存已冻结。实盘必须逐行填写，未填写不会当作零；差异行必须写原因。', 'Stock is frozen. Count every line explicitly; blank does not mean zero. Explain every difference.') : t('盘点已结束，记录保留供核对。', 'This stocktake is closed; evidence is retained.')" class="mb16" />
        <p>{{ t('未盘行数', 'Uncounted lines') }}: {{ detail.uncounted }} · {{ t('差异行数', 'Difference lines') }}: {{ detail.differenceLines }}</p>
        <div class="toolbar"><el-button :disabled="busy" @click="refresh">{{ t('刷新记录', 'Refresh count') }}</el-button><el-button v-if="detail.status === 'COUNTING' && can('found')" :disabled="blocked" @click="openFound">{{ t('补录盘盈商品', 'Add found stock') }}</el-button><el-button v-if="detail.status === 'COUNTING' && can('count')" type="primary" :loading="busy" :disabled="blocked || !dirtyLines.length" @click="saveCounts">{{ t('保存已修改实盘', 'Save edited counts') }} ({{ dirtyLines.length }})</el-button></div>
        <el-table :data="visibleLines" border row-key="id" :aria-label="t('盘点商品', 'Count lines')">
          <el-table-column prop="sku" label="SKU" min-width="140" fixed="left" /><el-table-column prop="locationName" :label="t('库位', 'Location')" min-width="110" /><el-table-column prop="batch" :label="t('批次', 'Batch')" min-width="100" /><el-table-column prop="serial" :label="t('串号', 'Serial')" min-width="110" /><el-table-column prop="expiry" :label="t('有效期', 'Expiry')" min-width="115" />
          <el-table-column prop="expected" :label="t('账面', 'Expected')" width="85" /><el-table-column prop="reserved" :label="t('预留', 'Reserved')" width="85" />
          <el-table-column :label="t('实盘数量', 'Counted quantity')" width="175"><template #default="{row}"><el-input-number v-if="detail.status === 'COUNTING' && can('count')" :key="row.id + String(blocked)" v-model="row.counted" :min="0" :max="row.serial ? 1 : Number.MAX_SAFE_INTEGER" :precision="0" :disabled="blocked" :aria-label="t('实盘数量 ', 'Counted quantity ') + row.sku" controls-position="right" /><span v-else>{{ row.counted ?? '—' }}</span></template></el-table-column>
          <el-table-column :label="t('差异', 'Difference')" width="90"><template #default="{row}">{{ row.counted == null ? '—' : row.counted - row.expected }}</template></el-table-column>
          <el-table-column :label="t('差异原因', 'Difference reason')" min-width="220"><template #default="{row}"><el-input v-if="detail.status === 'COUNTING' && can('count')" v-model="row.reason" :disabled="blocked" maxlength="500" :aria-label="t('差异原因 ', 'Difference reason ') + row.sku" /><span v-else>{{ row.reason || '—' }}</span></template></el-table-column>
        </el-table>
        <el-pagination v-if="editLines.length > 20" v-model:current-page="linePage" :page-size="20" :total="editLines.length" layout="prev, pager, next" class="line-pages" />
        <el-form v-if="foundOpen && detail.status === 'COUNTING'" label-position="top" :disabled="blocked" class="found-form" @submit.prevent>
          <h3>{{ t('补录账面以外的实物', 'Record physically found stock') }}</h3>
          <div class="grid"><el-form-item :label="t('商品', 'Product')"><el-select v-model="found.product" :aria-label="t('盘盈商品', 'Found product')" filterable remote :remote-method="q=>lookup('products',q,{client:detail.client})"><el-option v-for="o in options.products || []" :key="o.id" :value="o.id" :label="o.label" /></el-select></el-form-item>
          <el-form-item :label="t('库位', 'Location')"><el-select v-model="found.location" :aria-label="t('盘盈库位', 'Found location')"><el-option v-for="id in detail.locations" :key="id" :value="id" :label="label('locations',id)" /></el-select></el-form-item>
          <el-form-item :label="t('数量', 'Quantity')"><el-input-number v-model="found.counted" :min="1" :precision="0" :aria-label="t('盘盈数量', 'Found quantity')" /></el-form-item>
          <el-form-item v-for="f in tracking" :key="f.key" :label="t(f.zh,f.en)"><el-input v-model="found[f.key]" :aria-label="t('盘盈','Found ') + t(f.zh,f.en)" :placeholder="f.key==='expiry'?'YYYY-MM-DD':''" maxlength="191" /></el-form-item></div>
          <el-form-item :label="t('发现原因', 'Reason')"><el-input v-model="found.reason" :aria-label="t('盘盈原因', 'Found reason')" maxlength="500" /></el-form-item>
          <el-button type="primary" :loading="busy" @click="saveFound">{{ t('保存盘盈行', 'Save found line') }}</el-button><el-button @click="foundOpen=false">{{ t('收起', 'Hide') }}</el-button>
        </el-form>
        <p v-if="detail.approvalReason">{{ t('审核说明', 'Approval reason') }}: {{ detail.approvalReason }}</p><p v-if="detail.recountReason">{{ t('重盘原因', 'Recount reason') }}: {{ detail.recountReason }}</p><p v-if="detail.cancelReason">{{ t('取消原因', 'Cancellation reason') }}: {{ detail.cancelReason }}</p>
        <el-checkbox v-if="detail.status==='REVIEW' && detail.selfApprovalRequired && user.id===1 && can('approve')" v-model="selfApproval" :disabled="blocked">{{ t('管理员明确允许本次自审，原因将写入审计', 'Explicit administrator self-approval; reason will be audited') }}</el-checkbox>
      </template>
      <template #footer><el-button :disabled="busy" @click="opened=false">{{ t('关闭', 'Close') }}</el-button><template v-if="detail"><el-button v-for="a in actions" :key="a" :type="a==='cancel'?'danger':'primary'" :plain="a==='cancel'" :disabled="blocked || dirtyLines.length > 0 || a==='submit' && detail.uncounted > 0 || a==='approve' && detail.selfApprovalRequired && (user.id!==1 || !selfApproval)" @click="perform(a)">{{ actionLabel(a) }}</el-button></template></template>
    </el-drawer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, toRaw, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import auth from '@/plugins/auth'
import useUserStore from '@/store/modules/user'
import { bilingual as t } from '@/warehouse/i18n'
import { rejectedBeforeCommit } from '@/warehouse/inventory'
import { countOpen, startCountPayload, countPayload, foundPayload, countPendingKey, readPendingCount } from '@/warehouse/stocktakes'
import { listStocktakes, getStocktake, createStocktake, actionStocktake, getWarehouseLookups } from '@/api/warehouse'
const user=useUserStore(),can=a=>auth.hasPermi('warehouse:stocktakes:'+a)
const rows=ref([]),total=ref(0),page=ref(1),pageSize=ref(20),keyword=ref(''),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),pending=ref(null),pendingError=ref(''),startOpen=ref(false),opened=ref(false),detail=ref(null),options=reactive({}),editLines=ref([]),linePage=ref(1),foundOpen=ref(false),selfApproval=ref(false)
const form=reactive({client:'',warehouse:'',locations:[],reference:'',notes:''}),found=reactive({product:'',location:'',counted:1,batch:'',serial:'',expiry:'',reason:''})
const tracking=[{key:'batch',zh:'批次',en:'Batch'},{key:'serial',zh:'串号',en:'Serial'},{key:'expiry',zh:'有效期',en:'Expiry'}]
const blocked=computed(()=>busy.value||!!pending.value||!!pendingError.value),visibleLines=computed(()=>editLines.value.slice((linePage.value-1)*20,linePage.value*20))
const dirtyLines=computed(()=>editLines.value.filter(row=>{const original=detail.value?.lines.find(item=>item.id===row.id);return original&&(row.counted!==original.counted||row.reason!==original.reason)}))
const actions=computed(()=>!countOpen(detail.value)?[]:(detail.value.status==='COUNTING'?['submit','cancel']:['reopen','approve','cancel']).filter(can))
const status=value=>t(({COUNTING:'盘点中',REVIEW:'待复核',APPROVED:'已入账',CANCELLED:'已取消'})[value]||value,({COUNTING:'Counting',REVIEW:'Awaiting review',APPROVED:'Posted',CANCELLED:'Cancelled'})[value]||value)
const actionLabel=a=>t(({submit:'提交复核',reopen:'退回重盘',approve:'审核并调整库存',cancel:'取消并解冻'})[a],({submit:'Submit for review',reopen:'Request recount',approve:'Approve and post',cancel:'Cancel and unfreeze'})[a])
const label=(kind,id)=>options[kind]?.find(o=>o.id===id)?.label||id
const errors=e=>({count_required:t('请填写必填项。','Complete required fields.'),count_locations:t('请选择 1–100 个不重复的库位。','Select 1–100 distinct locations.'),count_quantity:t('实盘须明确填写非负整数，不能留空。','Enter an explicit nonnegative whole count.'),count_reason:t('有差异的行必须填写原因。','Explain every difference.'),count_serial:t('串号库存只能是 0 或 1 件。','Serial counts must be zero or one.'),count_lines:t('每次可保存 1–200 行，请分批保存。','Save 1–200 edited lines at a time.'),count_found:t('盘盈数量必须大于零，库位须在当前盘点范围。','Found stock must be positive and within this count’s locations.')})[e.message]||e.message||t('操作失败','Operation failed')
const tickets=new Map();async function lookup(kind,q='',scope={}){const n=(tickets.get(kind)||0)+1;tickets.set(kind,n);try{const r=await getWarehouseLookups(kind,q,kind==='locations'?{warehouse:scope.warehouse}:scope);if(tickets.get(kind)===n)options[kind]=kind==='locations'&&scope.client?r.data.filter(row=>!row.client||row.client===scope.client):r.data}catch(e){error.value=errors(e)}}
watch(()=>[form.client,form.warehouse],()=>{form.locations=[];options.locations=[];if(form.client&&form.warehouse)lookup('locations','',{client:form.client,warehouse:form.warehouse})})
let generation=0,detailGeneration=0
async function load(){const n=++generation;loading.value=true;try{const r=await listStocktakes({pageNum:page.value,pageSize:pageSize.value,keyword:keyword.value});if(n===generation){rows.value=r.rows;total.value=r.total}}catch(e){error.value=errors(e)}finally{if(n===generation)loading.value=false}}
function search(){page.value=1;load()}
function assign(row){detail.value=row;editLines.value=structuredClone(row.lines||[]);linePage.value=Math.min(linePage.value,Math.max(1,Math.ceil(editLines.value.length/20)));foundOpen.value=false;selfApproval.value=false;opened.value=true}
async function open(id){const n=++detailGeneration;try{const r=await getStocktake(id);if(n!==detailGeneration)return;assign(r.data);formError.value='';lookup('locations','',{client:r.data.client,warehouse:r.data.warehouse})}catch(e){error.value=errors(e)}}
async function refresh(){if(dirtyLines.value.length){try{await ElMessageBox.confirm(t('刷新将放弃尚未保存的实盘输入，是否继续？','Refreshing discards unsaved counts. Continue?'),t('刷新记录','Refresh count'))}catch{return}}await open(detail.value.id)}
function keep(value){sessionStorage.setItem(countPendingKey(user.id),JSON.stringify(value));pending.value=value}
async function send(retrying){try{const p=structuredClone(toRaw(pending.value)),r=p.type==='create'?await createStocktake(p.payload):await actionStocktake(p.id,p.payload);sessionStorage.removeItem(countPendingKey(user.id));pending.value=null;error.value='';formError.value='';startOpen.value=false;assign(r.data);ElMessage.success({message:t('盘点记录已保存','Stocktake saved'),grouping:true});await load()}catch(e){if(!retrying&&rejectedBeforeCommit(e)){sessionStorage.removeItem(countPendingKey(user.id));pending.value=null;formError.value=errors(e)}else formError.value=errors(e)+' · '+t('结果尚未确认，请重试原请求。','Result unconfirmed. Retry the original request.');error.value=formError.value}}
async function post(type,payload){keep({type,id:detail.value?.id,payload});await send(false)}
async function retry(){if(busy.value||!pending.value||!can(pending.value.type==='create'?'add':pending.value.payload.action))return;busy.value=true;try{await send(true)}finally{busy.value=false}}
async function create(){if(blocked.value||!can('add'))return;busy.value=true;formError.value='';try{await post('create',startCountPayload(form,crypto.randomUUID()))}catch(e){formError.value=errors(e)}finally{busy.value=false}}
async function saveCounts(){if(blocked.value||!can('count'))return;busy.value=true;formError.value='';try{await post('action',countPayload(detail.value,dirtyLines.value,crypto.randomUUID()))}catch(e){formError.value=errors(e)}finally{busy.value=false}}
function openFound(){foundOpen.value=true;Object.assign(found,{product:'',location:detail.value.locations[0],counted:1,batch:'',serial:'',expiry:'',reason:''});lookup('products','',{client:detail.value.client})}
async function saveFound(){if(blocked.value||!can('found'))return;if(dirtyLines.value.length){formError.value=t('请先保存实盘输入，再补录盘盈。','Save edited counts before adding found stock.');return}busy.value=true;formError.value='';try{await post('action',foundPayload(detail.value,found,crypto.randomUUID()))}catch(e){formError.value=errors(e)}finally{busy.value=false}}
async function perform(action){if(blocked.value||dirtyLines.value.length||!actions.value.includes(action))return;busy.value=true;formError.value='';try{let reason='';try{if(action==='submit')await ElMessageBox.confirm(t('提交后实盘输入会锁定，等待复核。','Submit locks count entry for review.'),actionLabel(action),{confirmButtonText:t('确认','Confirm'),cancelButtonText:t('取消','Cancel')});else{const r=await ElMessageBox.prompt(action==='reopen'?t('退回会清空实盘数并保留旧记录，库存继续冻结。请填写原因。','Recount clears entered numbers, retains evidence and keeps stock frozen. Enter a reason.'):t('请填写原因。审核入账会按实盘调整库存；取消只解冻，不调整库存。','Enter a reason. Approval posts physical differences; cancellation only unfreezes stock.'),actionLabel(action),{inputValidator:v=>!!v?.trim()&&v.length<=500||t('请填写原因','Enter a reason'),confirmButtonText:t('确认','Confirm'),cancelButtonText:t('取消','Cancel')});reason=r.value}}catch{return}await post('action',{requestId:crypto.randomUUID(),_version:detail.value._version,action,...(action!=='submit'?{reason}:{}),...(action==='approve'?{selfApproval:selfApproval.value}:{})})}catch(e){formError.value=errors(e)}finally{busy.value=false}}
onMounted(async()=>{try{pending.value=readPendingCount(sessionStorage,user.id)}catch{pendingError.value=t('上次请求记录损坏，请联系管理员核对后再操作。','The saved request cannot be read. Ask an administrator to reconcile it.')}await Promise.all([load(),lookup('clients'),lookup('warehouses')])})
</script>
<style scoped>
.heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:20px}.heading h2{margin:0;font-size:20px}.heading h3{margin:0;font-size:17px;overflow-wrap:anywhere}.mb16{margin-bottom:16px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.toolbar .el-button{margin-left:0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.found-form{margin-top:24px;border:1px solid var(--el-border-color);border-radius:6px;padding:16px}.line-pages{margin-top:16px}.el-select{width:100%}.el-input-number{width:150px}.stocktakes :deep(.el-drawer__footer){display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px}.stocktakes :deep(.el-drawer__footer .el-button){margin-left:0}@media(max-width:600px){.grid{grid-template-columns:1fr}.heading{align-items:flex-start}.found-form{padding:12px}}
</style>
